        uiMapID=target.uiMapID,instanceID=target.instanceID,seconds=seconds,copper=w.moneyAssigned and 0 or w.copper,
        label=Label(w.hint,w.kind),instruction=Label(w.hint,w.kind),generated=true,mandatory=true,v2=true,
        sourceFree=w.hint.sourceFree==true,movementMode=w.segment.mode,edgeId=w.segment.edgeId}
