        key=tostring(request.contextKey or 'normal')..':'..tostring(request.generation or 0),
        started=started or 0,last=started or 0,cpuMs=0,slices=0,maxSliceMilliseconds=0,
        totalSliceMilliseconds=0,elapsedMilliseconds=0,phase='open',status='planning'},Job)
